def execute(ctx):
    body = ctx.body or {}
    nodes = ctx.nodes or {}
    seed = nodes.get('seed') or {}
    # 触发入参既可从 ctx.body 读，也可从上游 seed 读
    name = body.get('name') or seed.get('name') or 'onebase'
    def as_num(v):
        try:
            return float(v)
        except (TypeError, ValueError):
            return 0.0
    a = as_num(body.get('a', seed.get('a')))
    b = as_num(body.get('b', seed.get('b')))
    total = a + b
    if total == int(total):
        total = int(total)
    return {
        'result': {
            'engine': 'python',
            'sum': total,
            'greeting': 'hello ' + str(name),
            'sha256_of_name': crypto.sha256(str(name)),
            'has_api_token': bool(env.get('API_TOKEN')),
            'server_ts_ms': time.now_ms(),
            'echo_body': body
        }
    }
